local register = register
local open = io.open
local format = string.format
local tostring = tostring

local password_file = "/etc/openvpn/psw-file"

local function users()
    local result = {}
    local fd = open(password_file, "r")
    if not fd then return result end
    for line in fd:lines() do
        local username = line:match("^([^%s]+)%s+")
        if username then
            result[#result + 1] = {
                id = "user" .. tostring(#result + 1),
                username = username,
                password = line:match("^[^%s]+%s+(.*)$") or ""
            }
        end
    end
    fd:close()
    return result
end

local function rewrite(action, key, param, value)
    local current = users()
    local index = tonumber((key or ""):match("^user(%d+)$"))
    if not index and action ~= "add" then return nil end

    if action == "add" then
        current[#current + 1] = { id = "user" .. tostring(#current + 1), username = "vpn_user", password = "!" }
    elseif action == "delete" then
        if not index or not current[index] then return nil end
        table.remove(current, index)
    elseif current[index] then
        if param == "username" then
            if not value or not value:match("^[%w_.@-]+$") then return nil end
            for i, user in ipairs(current) do
                if i ~= index and user.username == value then return nil end
            end
            current[index].username = value
        elseif param == "password" then
            if not value or #value < 8 or value:find("%s") then return nil end
            current[index].password = value
        end
    else
        return nil
    end
    local fd = open(password_file, "w")
    if not fd then return nil end
    for _, user in ipairs(current) do
        fd:write(format("%s\t%s\n", user.username, user.password or "!"))
    end
    fd:close()
    return true
end

local parent_mapping = {
    objectType = {
        name = "rpc.openvpn.server.user.",
        access = "readOnly",
        minEntries = 1,
        maxEntries = 1,
        parameters = {},
    },
}
register(parent_mapping)

local mapping = {
    objectType = {
        name = "rpc.openvpn.server.user.@.",
        access = "readWrite",
        minEntries = 0,
        maxEntries = 32,
        parameters = {
            username = { access = "readWrite", type = "string" },
            password = { access = "readWrite", type = "password" },
        },
    },
}
mapping.entries = function()
    local result = {}
    for _, user in ipairs(users()) do result[#result + 1] = user.id end
    return result
end
mapping.get = function(_, param, key)
    local index = tonumber((key or ""):match("^user(%d+)$"))
    local user = index and users()[index]
    if not user then return "" end
    if param == "username" then return user.username end
    if param == "password" then return "********" end
    return ""
end
mapping.set = function(_, param, value, key) return rewrite("set", key, param, value) end
mapping.add = function() rewrite("add", "user1"); return "user" .. tostring(#users()) end
mapping.delete = function(_, key) return rewrite("delete", key) end
mapping.commit = function() end
mapping.revert = function() end
register(mapping)
